import 'carepoint_localization.dart';

String journeyText(CarePointLocale locale, String key) {
  final index = switch (locale) { CarePointLocale.ar => 1, CarePointLocale.fr => 2, CarePointLocale.es => 3, _ => 0 };
  return journeyLabels[key]?[index] ?? key;
}

